        </div>
        <div className="flex items-center gap-4">
          <span className="text-slate-600 hidden md:inline">{userProfile.full_name}</span>
          <button 
            onClick={() => supabase.auth.signOut()}
            className="flex items-center gap-2 text-red-500 hover:bg-red-50 px-4 py-2 rounded-lg transition"
          >
            <LogOut className="w-4 h-4" /> خروج
          </button>
        </div>
      </nav>

      <main className="max-w-4xl mx-auto p-6 space-y-8">
        {/* Welcome Section */}
        <div className="bg-emerald-600 rounded-2xl p-8 text-white shadow-xl relative overflow-hidden">
          <div className="relative z-10">
            <h2 className="text-2xl font-bold mb-2">أهلاً بك، {userProfile.full_name}</h2>
            <p className="opacity-90">يمكنك هنا إدارة رابط ملفات الأداء الخاصة بك ومتابعة نتائج تقييماتك.</p>
          </div>
          <div className="absolute top-0 left-0 w-64 h-64 bg-white/10 rounded-full -translate-x-1/2 -translate-y-1/2 blur-3xl"></div>
        </div>

        {/* Link Submission */}
        <div className="bg-white rounded-2xl p-8 shadow-sm border border-slate-100">
          <h3 className="text-lg font-bold mb-6 flex items-center gap-2">
