                        onShowReport={(evalData) => setEvaluationToShow({ staff: s, evaluation: evalData })} 
                        onShareWhatsApp={(score) => handleShareWhatsApp(s, score)}
                      />
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
          {filteredStaff.length === 0 && (
            <div className="p-12 text-center text-slate-500">
              لا يوجد موظفون مسجلون بهذا التصنيف حالياً.
            </div>
          )}
        </div>
      </main>

      {/* Modals */}
      {selectedStaff && (
        <EvaluationModal 
          staff={selectedStaff} 
          onClose={() => {
            setSelectedStaff(null);
            fetchStaff();
          }} 
        />
      )}

      {evaluationToShow && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center p-4">
