import React, { useState } from 'react';
import { Profile, UserRole } from '../types';
import { CRITERIA_MAP } from '../constants';
import { supabase } from '../supabase';
import { X, Save, AlertCircle } from 'lucide-react';

interface Props {
  staff: Profile;
  onClose: () => void;
}

const EvaluationModal: React.FC<Props> = ({ staff, onClose }) => {
  const criteria = CRITERIA_MAP[staff.role];
  const [scores, setScores] = useState<Record<number, number>>({});
  const [comments, setComments] = useState('');
  const [submitting, setSubmitting] = useState(false);

  const calculateTotal = () => {
    const totalWeights = criteria.reduce((sum, c) => sum + c.weight, 0);
    const weightedSum = criteria.reduce((sum, c) => {
      const score = scores[c.id] || 0;
      return sum + (score * (c.weight / 100));
    }, 0);
    // Normalize to 100% based on user criteria weights
    // Since some lists sum to 110, we treat weight as absolute and sum to the list total
    return Math.round(weightedSum);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (Object.keys(scores).length < criteria.length) {
      alert('يرجى تقييم جميع المعايير');
      return;
    }
    setSubmitting(true);

    const { data: { user } } = await supabase.auth.getUser();

    const { error } = await supabase.from('evaluations').insert({
      staff_id: staff.id,
      evaluator_id: user?.id,
      scores,
      total_score: calculateTotal(),
      comments
    });

    if (error) alert(error.message);
    else {
      alert('تم حفظ التقييم بنجاح');
      onClose();
    }
    setSubmitting(false);
  };

  return (
    <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center p-4">
      <div className="bg-white w-full max-w-4xl max-h-[90vh] rounded-3xl overflow-hidden flex flex-col shadow-2xl">
        <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
          <div>
            <h2 className="text-xl font-bold text-slate-800">تقييم أداء: {staff.full_name}</h2>
            <p className="text-slate-500 text-sm">التصنيف الوظيفي: {staff.role}</p>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-white rounded-full transition shadow-sm border border-slate-100">
            <X className="w-6 h-6 text-slate-400" />
          </button>
        </div>

        <div className="flex-1 overflow-auto p-6">
          <form id="eval-form" onSubmit={handleSubmit} className="space-y-6">
            <div className="grid gap-4">
              {criteria.map((c, idx) => (
                <div key={c.id} className="bg-slate-50 p-4 rounded-2xl border border-slate-100 group hover:border-emerald-200 transition">
                  <div className="flex justify-between items-start mb-4">
                    <div className="flex gap-3">
                      <span className="bg-emerald-600 text-white w-7 h-7 flex items-center justify-center rounded-full text-xs font-bold shrink-0">
                        {idx + 1}
                      </span>
                      <p className="text-slate-800 font-medium leading-relaxed">{c.text}</p>
                    </div>
                    <span className="text-xs font-bold text-emerald-600 bg-emerald-50 px-2 py-1 rounded">الوزن: {c.weight}%</span>
                  </div>
                  <div className="flex items-center gap-4">
                    <input
                      type="range"
                      min="0"
                      max="100"
                      step="1"
                      className="flex-1 accent-emerald-600 h-2 bg-slate-200 rounded-lg appearance-none cursor-pointer"
                      value={scores[c.id] || 0}
                      onChange={(e) => setScores({ ...scores, [c.id]: parseInt(e.target.value) })}
                    />
                    <div className="w-16">
                      <input
                        type="number"
                        min="0"
                        max="100"
                        className="w-full px-2 py-1 text-center font-bold text-emerald-700 bg-white border border-slate-200 rounded-lg focus:ring-2 focus:ring-emerald-500 outline-none"
                        value={scores[c.id] || 0}
                        onChange={(e) => setScores({ ...scores, [c.id]: Math.min(100, Math.max(0, parseInt(e.target.value) || 0)) })}
                      />
                    </div>
                  </div>
                </div>
              ))}
            </div>

            <div className="space-y-2">
              <label className="block font-bold text-slate-700">ملاحظات إضافية (اختياري)</label>
              <textarea
                className="w-full px-4 py-3 rounded-2xl border border-slate-200 focus:ring-2 focus:ring-emerald-500 outline-none h-32 resize-none"
                placeholder="اكتب أي ملاحظات أو توصيات هنا..."
                value={comments}
                onChange={(e) => setComments(e.target.value)}
              ></textarea>
            </div>
          </form>
        </div>

        <div className="p-6 border-t bg-slate-50/80 flex flex-col md:flex-row justify-between items-center gap-4">
          <div className="flex items-center gap-2">
             <AlertCircle className="w-5 h-5 text-amber-500" />
             <span className="text-sm font-medium text-slate-600">سيتم حساب الدرجة النهائية تلقائياً بناءً على الأوزان النسبية.</span>
          </div>
          <div className="flex items-center gap-6">
            <div className="text-right">
              <span className="text-xs text-slate-500 block">النتيجة الإجمالية</span>
              <span className="text-3xl font-black text-emerald-600">{calculateTotal()}%</span>
            </div>
            <button
              form="eval-form"
              disabled={submitting}
              className="bg-emerald-600 text-white px-10 py-3 rounded-2xl font-bold shadow-lg shadow-emerald-200 hover:bg-emerald-700 transition flex items-center gap-2 disabled:opacity-50"
            >
              <Save className="w-5 h-5" /> {submitting ? 'جاري الحفظ...' : 'اعتماد التقييم'}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default EvaluationModal;

