          <div className="flex items-center gap-2 w-full md:w-auto">
            <Filter className="w-5 h-5 text-slate-400" />
            <select
              className="w-full md:w-48 px-4 py-2 rounded-xl border border-slate-200 focus:ring-2 focus:ring-emerald-500 outline-none"
