                <th className="px-6 py-4">الحالة</th>
                <th className="px-6 py-4 text-center">الإجراءات</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredStaff.map((s) => (
                <tr key={s.id} className="hover:bg-slate-50/80 transition group">
                  <td className="px-6 py-4">
                    <div className="font-semibold text-slate-800">{s.full_name}</div>
                    <div className="text-xs text-slate-500">{s.mobile}</div>
                  </td>
                  <td className="px-6 py-4 text-slate-600 font-medium">{s.role}</td>
                  <td className="px-6 py-4">
                    {s.drive_link ? (
                      <a 
                        href={s.drive_link} 
                        target="_blank" 
                        rel="noopener noreferrer"
                        className="text-emerald-700 hover:text-emerald-800 flex items-center gap-1 font-medium underline decoration-emerald-200"
                      >
                        <ExternalLink className="w-4 h-4" /> عرض الشواهد
                      </a>
                    ) : (
                      <span className="text-slate-400 italic text-sm">لم يرفع رابط</span>
                    )}
                  </td>
                  <td className="px-6 py-4">
                    <StatusBadge staffId={s.id} />
                  </td>
                  <td className="px-6 py-4">
                    <div className="flex items-center justify-center gap-2">
                      <button
                        onClick={() => setSelectedStaff(s)}
                        className="bg-emerald-600 text-white px-4 py-2 rounded-lg text-sm font-bold hover:bg-emerald-700 transition flex items-center gap-2 shadow-sm"
                      >
                        <Star className="w-4 h-4" /> تقييم
                      </button>
