                      />
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
          {filteredStaff.length === 0 && (
            <div className="p-12 text-center text-slate-500">
              لا يوجد موظفون مسجلون بهذا التصنيف حالياً.
            </div>
          )}
        </div>
      </main>

      {/* Modals */}
      {selectedStaff && (
        <EvaluationModal 
          staff={selectedStaff} 
          onClose={() => {
            setSelectedStaff(null);
            fetchStaff();
          }} 
        />
      )}

      {evaluationToShow && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-5xl h-[90vh] rounded-3xl overflow-hidden flex flex-col shadow-2xl">
            <div className="p-4 border-b flex justify-between items-center bg-slate-50 no-print">
              <h2 className="text-xl font-bold font-amiri text-emerald-800">معاينة تقرير الأداء المعتمد</h2>
              <div className="flex gap-2">
                <button 
                  onClick={() => window.print()} 
                  className="bg-emerald-700 text-white px-6 py-2 rounded-xl flex items-center gap-2 shadow-lg"
                >
                  <Printer className="w-4 h-4" /> طباعة التقرير
                </button>
                <button 
                  onClick={() => setEvaluationToShow(null)} 
                  className="bg-white border border-slate-200 text-slate-600 px-6 py-2 rounded-xl hover:bg-slate-50 transition"
                >
                  إغلاق
                </button>
              </div>
            </div>
            <div className="flex-1 overflow-auto p-12 bg-white" id="printable-area">
              <PrintableReport 
                staff={evaluationToShow.staff} 
                evaluation={evaluationToShow.evaluation} 
                principalName={userProfile.full_name}
              />
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const StatusBadge: React.FC<{ staffId: string }> = ({ staffId }) => {
  const [evaluated, setEvaluated] = useState(false);
  useEffect(() => {
    supabase.from('evaluations').select('id').eq('staff_id', staffId).limit(1).then(({ data }) => {
      setEvaluated(!!data?.length);
    });
  }, [staffId]);

  return evaluated ? (
    <span className="bg-emerald-100 text-emerald-800 px-3 py-1 rounded-full text-xs font-bold border border-emerald-200">مقيّم معتمد</span>
  ) : (
    <span className="bg-amber-50 text-amber-700 px-3 py-1 rounded-full text-xs font-bold border border-amber-200">قيد الانتظار</span>
  );
};

const EvaluationActions: React.FC<{ staff: Profile, onShowReport: (ev: any) => void, onShareWhatsApp: (score: number) => void }> = ({ staff, onShowReport, onShareWhatsApp }) => {
  const [evalData, setEvalData] = useState<any>(null);

  useEffect(() => {
    supabase.from('evaluations')
      .select('*')
      .eq('staff_id', staff.id)
      .order('created_at', { ascending: false })
      .limit(1)
      .single()
      .then(({ data }) => setEvalData(data));
  }, [staff.id]);

  if (!evalData) return null;

  return (
    <div className="flex gap-1">
      <button 
        onClick={() => onShowReport(evalData)}
        className="p-2 text-slate-500 hover:bg-emerald-50 hover:text-emerald-700 rounded-lg transition" 
        title="طباعة التقرير"
      >
        <Printer className="w-4 h-4" />
      </button>
      <button 
        onClick={() => onShareWhatsApp(evalData.total_score)}
        className="p-2 text-emerald-600 hover:bg-emerald-50 rounded-lg transition" 
        title="إرسال النتيجة عبر واتساب"
      >
        <MessageCircle className="w-4 h-4" />
      </button>
    </div>
  );
};

