import React, { useState } from 'react';
import { supabase } from '../supabase';
import { KeyRound, Phone, UserPlus, LogIn, School } from 'lucide-react';

const Login: React.FC<{ onLogin: () => void }> = ({ onLogin }) => {
  const [mobile, setMobile] = useState('');
  const [password, setPassword] = useState('');
  const [isRegistering, setIsRegistering] = useState(false);
  const [loading, setLoading] = useState(false);

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!mobile.match(/^05\d{8}$/)) {
      alert('يرجى إدخال رقم جوال سعودي صحيح (يبدأ بـ 05 ويتكون من 10 أرقام)');
      return;
    }

    setLoading(true);
    // تحويل رقم الجوال داخلياً لصيغة إيميل ليتوافق مع Supabase Auth
    const internalEmail = `${mobile}@school.local`;

    const { error } = isRegistering 
      ? await supabase.auth.signUp({ email: internalEmail, password })
      : await supabase.auth.signInWithPassword({ email: internalEmail, password });

    if (error) {
      if (error.message.includes('already registered')) {
        alert('هذا الرقم مسجل مسبقاً، يرجى تسجيل الدخول');
      } else {
        alert('خطأ: ' + error.message);
      }
    } else {
      onLogin();
    }
    setLoading(false);
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-emerald-50 to-blue-50 p-4">
      <div className="w-full max-w-md bg-white rounded-3xl shadow-2xl overflow-hidden border border-white/50">
        <div className="bg-emerald-800 p-8 text-white text-center">
          <School className="w-16 h-16 mx-auto mb-4 text-emerald-100" />
          <h1 className="text-2xl font-bold font-amiri leading-relaxed">ثانوية الأمير عبدالمجيد الأولى</h1>
          <p className="mt-2 text-emerald-100 text-sm font-medium">نظام إتقان للتقييم الوظيفي</p>
        </div>

        <div className="p-8">
          <div className="mb-6 text-center">
            <h2 className="text-xl font-bold text-slate-800">
              {isRegistering ? 'إنشاء حساب جديد' : 'تسجيل الدخول'}
            </h2>
            <p className="text-slate-500 text-sm mt-1">استخدم رقم جوالك للوصول للنظام</p>
          </div>

          <form onSubmit={handleAuth} className="space-y-6">
            <div className="space-y-4">
              <div className="relative">
                <Phone className="absolute right-3 top-3 w-5 h-5 text-slate-400" />
                <input
                  type="tel"
                  placeholder="رقم الجوال (05xxxxxxxx)"
                  required
                  className="w-full pr-10 pl-4 py-3 rounded-xl border border-slate-200 focus:ring-2 focus:ring-emerald-500 outline-none transition font-sans"
                  value={mobile}
                  onChange={(e) => setMobile(e.target.value)}
                  dir="ltr"
                />
              </div>
              <div className="relative">
                <KeyRound className="absolute right-3 top-3 w-5 h-5 text-slate-400" />
                <input
                  type="password"
                  placeholder="كلمة المرور"
                  required
                  className="w-full pr-10 pl-4 py-3 rounded-xl border border-slate-200 focus:ring-2 focus:ring-emerald-500 outline-none transition"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                />
              </div>
            </div>

            <button
              disabled={loading}
              className="w-full bg-emerald-600 text-white py-3 rounded-xl font-bold text-lg shadow-lg hover:bg-emerald-700 transition flex items-center justify-center gap-2 disabled:opacity-50"
            >
              {loading ? (
                <span className="animate-spin text-xl">⌛</span>
              ) : isRegistering ? (
                <><UserPlus className="w-5 h-5" /> تسجيل جديد</>
              ) : (
                <><LogIn className="w-5 h-5" /> دخول</>
              )}
            </button>
          </form>

          <div className="mt-6 text-center">
            <button
              onClick={() => setIsRegistering(!isRegistering)}
              className="text-emerald-700 font-bold hover:underline transition"
            >
              {isRegistering ? 'لديك حساب؟ سجل دخولك' : 'ليس لديك حساب؟ سجل رقم جوالك الآن'}
            </button>
          </div>

          <p className="mt-8 text-xs text-slate-400 text-center leading-relaxed">
            * رقم الجوال المستخدم سيكون هو وسيلة التواصل الأساسية لإرسال نتائج التقييم عبر الواتساب.
          </p>
        </div>
      </div>
    </div>
  );
};

