const Login: React.FC<{ onLogin: () => void }> = ({ onLogin }) => {
  const [mobile, setMobile] = useState('');
  const [password, setPassword] = useState('');
  const [isRegistering, setIsRegistering] = useState(false);
  const [loading, setLoading] = useState(false);
  const [serverStatus, setServerStatus] = useState<'checking' | 'online' | 'offline'>('checking');

  const checkConnection = async () => {
    setServerStatus('checking');
    try {
      // محاولة استعلام بسيطة جداً لاختبار الاتصال
      const { error } = await supabase.from('profiles').select('id').limit(1);
      if (error && (error.message.includes('fetch') || error.code === 'PGRST116')) {
         // PGRST116 تعني لا يوجد بيانات، وهذا جيد للاتصال
         setServerStatus('online');
      } else if (error) {
         setServerStatus('offline');
      } else {
         setServerStatus('online');
      }
    } catch (err) {
      setServerStatus('offline');
    }
  };

  useEffect(() => {
    checkConnection();
  }, []);

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!mobile.match(/^05\d{8}$/)) {
      alert('يرجى إدخال رقم جوال سعودي صحيح يبدأ بـ 05');
      return;
    }

    setLoading(true);
    const internalEmail = `${mobile}@school.local`;

    try {
      if (isRegistering) {
        const { data, error } = await supabase.auth.signUp({ 
          email: internalEmail, 
          password,
          options: { data: { mobile_number: mobile } }
        });

        if (error) throw error;

        if (data.user && !data.session) {
          alert('تم إنشاء الحساب بنجاح. يرجى من المدير التأكد من إيقاف "Confirm email" في لوحة تحكم Supabase لتتمكن من الدخول مباشرة.');
          setIsRegistering(false);
        } else if (data.session) {
          onLogin();
        }
      } else {
        const { error } = await supabase.auth.signInWithPassword({ 
          email: internalEmail, 
          password 
        });
        if (error) throw error;
        onLogin();
      }
    } catch (err: any) {
      console.error('Auth Error:', err);
      if (err.message.includes('fetch')) {
        setServerStatus('offline');
        alert('❌ لا يمكن الوصول لخادم قاعدة البيانات. يرجى التأكد من أن المشروع في Supabase في حالة Active وليس Paused.');
      } else if (err.message.includes('Invalid login')) {
        alert('رقم الجوال أو كلمة المرور غير صحيحة.');
      } else {
        alert('خطأ: ' + err.message);
      }
    } finally {
      setLoading(false);
    }
