          <School className="w-20 h-20 mx-auto mb-4 text-emerald-200" />
          <h1 className="text-3xl font-bold font-amiri tracking-wide">ثانوية الأمير عبدالمجيد الأولى</h1>
          <p className="mt-2 text-emerald-200/80 text-sm font-light uppercase tracking-widest">نظام إتقان للتقييم الوظيفي</p>
        </div>

        <div className="p-10">
          <div className="mb-8 text-center">
            <h2 className="text-2xl font-extrabold text-slate-800">
              {isRegistering ? 'تسجيل مستخدم جديد' : 'تسجيل الدخول'}
            </h2>
            <p className="text-slate-500 text-sm mt-2">أهلاً بك في منصة التقييم الرسمية للمدرسة</p>
          </div>

          <form onSubmit={handleAuth} className="space-y-5">
            <div className="space-y-3">
              <div className="relative group">
                <Phone className="absolute right-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400 group-focus-within:text-emerald-600 transition-colors" />
                <input
                  type="tel"
                  placeholder="رقم الجوال (05xxxxxxxx)"
                  required
                  className="w-full pr-12 pl-4 py-4 bg-slate-50 rounded-2xl border border-slate-200 focus:border-emerald-500 focus:ring-4 focus:ring-emerald-500/10 outline-none transition-all font-sans"
                  value={mobile}
                  onChange={(e) => setMobile(e.target.value)}
                  dir="ltr"
                />
              </div>
              <div className="relative group">
                <KeyRound className="absolute right-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400 group-focus-within:text-emerald-600 transition-colors" />
                <input
                  type="password"
