import React, { useState, useEffect } from 'react';
import { supabase, testSupabaseConnection } from './supabase';
import { Profile, UserRole } from './types';
import Login from './components/Login';
import Dashboard from './components/Dashboard';
import PrincipalDashboard from './components/PrincipalDashboard';
import { Loader2, User, Phone, Briefcase, GraduationCap, ShieldCheck, Users, Beaker, ClipboardCheck, WifiOff, RefreshCw } from 'lucide-react';

function App() {
  const [session, setSession] = useState<any>(null);
  const [profile, setProfile] = useState<Profile | null>(null);
  const [loading, setLoading] = useState(true);
  const [connectionError, setConnectionError] = useState(false);

  const initApp = async () => {
    setLoading(true);
    setConnectionError(false);
    try {
      const { data: { session } } = await supabase.auth.getSession();
      setSession(session);
      if (session) {
        await fetchProfile(session.user.id);
      } else {
        setLoading(false);
      }
    } catch (err: any) {
      if (err.message?.includes('fetch')) {
        setConnectionError(true);
      }
      setLoading(false);
    }
  };

  useEffect(() => {
    initApp();

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
      if (session) fetchProfile(session.user.id);
      else {
        setProfile(null);
        setLoading(false);
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  const fetchProfile = async (userId: string) => {
    try {
      const { data, error } = await supabase
        .from('profiles')
        .select('*')
        .eq('id', userId)
        .single();

      if (error && error.code !== 'PGRST116') {
        if (error.message.includes('fetch')) throw error;
      }
      setProfile(data);
    } catch (error) {
      console.error('Error fetching profile:', error);
      setConnectionError(true);
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-slate-50 gap-4">
        <Loader2 className="w-12 h-12 text-emerald-600 animate-spin" />
        <p className="text-slate-500 font-medium animate-pulse">جاري الاتصال بقاعدة البيانات...</p>
      </div>
    );
  }

  if (connectionError) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-red-50 p-4">
        <div className="max-w-md w-full bg-white p-8 rounded-3xl shadow-xl border border-red-100 text-center">
          <div className="w-20 h-20 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-6">
            <WifiOff className="w-10 h-10 text-red-600" />
          </div>
          <h2 className="text-2xl font-bold text-slate-800 mb-4">فشل الاتصال بالخادم</h2>
          <p className="text-slate-600 mb-8 leading-relaxed">
            حدث خطأ أثناء محاولة الوصول إلى قاعدة البيانات. يرجى التأكد من أن مشروع Supabase ليس في وضع الإسبات (Paused) ومن جودة اتصال الإنترنت لديك.
          </p>
          <button 
            onClick={initApp}
            className="w-full bg-emerald-600 text-white py-4 rounded-2xl font-bold shadow-lg hover:bg-emerald-700 transition flex items-center justify-center gap-2"
          >
            <RefreshCw className="w-5 h-5" /> إعادة محاولة الاتصال
          </button>
        </div>
      </div>
    );
  }

  if (!session) {
    return <Login onLogin={() => {}} />;
  }

  if (!profile) {
    const mobileFromAuth = session.user.email?.split('@')[0] || '';
    return <CompleteProfile userId={session.user.id} mobile={mobileFromAuth} onComplete={() => fetchProfile(session.user.id)} />;
  }

  return profile.role === UserRole.PRINCIPAL ? (
    <PrincipalDashboard userProfile={profile} />
  ) : (
    <Dashboard userProfile={profile} />
  );
}

const CompleteProfile: React.FC<{ userId: string; mobile: string; onComplete: () => void }> = ({ userId, mobile, onComplete }) => {
  const [name, setName] = useState('');
  const [role, setRole] = useState<UserRole>(UserRole.TEACHER);
  const [submitting, setSubmitting] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!name) {
      alert('يرجى إدخال الاسم الكامل');
      return;
    }
    setSubmitting(true);
    const { error } = await supabase.from('profiles').insert({
      id: userId,
      full_name: name,
      mobile: mobile,
      role
    });
    if (error) {
      if (error.message.includes('duplicate key')) {
        alert('رقم الجوال هذا مستخدم بالفعل في حساب آخر');
      } else {
        alert(error.message);
      }
    } else {
      onComplete();
    }
    setSubmitting(false);
  };

  const rolesConfig = [
    { role: UserRole.TEACHER, icon: GraduationCap, desc: 'تقديم الدروس وإدارة الفصول' },
    { role: UserRole.VICE_PRINCIPAL, icon: Users, desc: 'المساندة الإدارية والتعليمية' },
    { role: UserRole.COUNSELOR, icon: ClipboardCheck, desc: 'توجيه وإرشاد الطلاب' },
    { role: UserRole.LAB_ASSISTANT, icon: Beaker, desc: 'إدارة المختبرات والتجارب' },
    { role: UserRole.PRINCIPAL, icon: ShieldCheck, desc: 'الإدارة العامة للمدرسة' },
  ];

  return (
    <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-emerald-50 to-slate-100 p-4 font-cairo">
      <div className="bg-white p-8 rounded-[2rem] shadow-2xl w-full max-w-2xl border border-white">
        <div className="text-center mb-8">
          <div className="bg-emerald-100 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4">
            <User className="w-8 h-8 text-emerald-600" />
          </div>
          <h2 className="text-3xl font-bold text-slate-800 font-amiri">إكمال البيانات الشخصية</h2>
          <p className="text-slate-500 mt-2">رقم جوالك المسجل: <span className="font-bold text-emerald-700 dir-ltr">{mobile}</span></p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-8">
          <div className="relative">
            <label className="block text-sm font-bold text-slate-700 mb-2 mr-1">الاسم الكامل</label>
            <div className="relative">
              <User className="absolute right-3 top-3 w-5 h-5 text-slate-400" />
              <input
                required
                placeholder="أدخل اسمك الثلاثي"
                className="w-full pr-10 pl-4 py-4 rounded-2xl border border-slate-200 focus:ring-4 focus:ring-emerald-500/10 focus:border-emerald-500 outline-none transition"
                value={name}
                onChange={(e) => setName(e.target.value)}
              />
            </div>
          </div>

          <div>
            <label className="block text-sm font-bold text-slate-700 mb-4 mr-1 flex items-center gap-2">
              <Briefcase className="w-4 h-4 text-emerald-600" /> المسمى الوظيفي الحالي في المدرسة
            </label>
            <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-3">
              {rolesConfig.map((item) => (
                <button
                  key={item.role}
                  type="button"
                  onClick={() => setRole(item.role)}
                  className={`flex flex-col items-center p-4 rounded-2xl border-2 transition-all duration-300 text-center space-y-2 ${
                    role === item.role
                      ? 'border-emerald-600 bg-emerald-50 ring-4 ring-emerald-600/10 scale-105'
                      : 'border-slate-100 bg-slate-50 hover:border-emerald-200 hover:bg-white'
                  }`}
                >
                  <item.icon className={`w-8 h-8 ${role === item.role ? 'text-emerald-600' : 'text-slate-400'}`} />
                  <span className={`font-bold text-sm ${role === item.role ? 'text-emerald-700' : 'text-slate-600'}`}>{item.role}</span>
                  <span className="text-[10px] text-slate-400 leading-tight">{item.desc}</span>
                </button>
              ))}
            </div>
          </div>

          <button
            disabled={submitting}
            className="w-full bg-emerald-700 text-white py-4 rounded-2xl font-bold text-lg shadow-xl shadow-emerald-900/10 hover:bg-emerald-800 transition transform hover:-translate-y-1 active:translate-y-0 disabled:opacity-50"
          >
            {submitting ? (
              <div className="flex items-center justify-center gap-2">
                <Loader2 className="w-6 h-6 animate-spin" />
                جاري إعداد الملف الشخصي...
              </div>
            ) : 'تأكيد وحفظ البيانات والبدء'}
          </button>
        </form>
      </div>
    </div>
  );
};

export default App;

