  ShieldCheck, Users, Beaker, ClipboardCheck 
} from 'lucide-react';

const Login: React.FC<{ onLogin: () => void }> = ({ onLogin }) => {
  const [mobile, setMobile] = useState('');
  const [password, setPassword] = useState('');
  const [fullName, setFullName] = useState('');
  const [role, setRole] = useState<UserRole>(UserRole.TEACHER);
  const [isRegistering, setIsRegistering] = useState(false);
  const [loading, setLoading] = useState(false);
  const [serverStatus, setServerStatus] = useState<'checking' | 'online' | 'offline'>('checking');

  const rolesConfig = [
    { role: UserRole.TEACHER, icon: GraduationCap },
    { role: UserRole.VICE_PRINCIPAL, icon: Users },
    { role: UserRole.COUNSELOR, icon: ClipboardCheck },
    { role: UserRole.LAB_ASSISTANT, icon: Beaker },
    { role: UserRole.PRINCIPAL, icon: ShieldCheck },
  ];

  const checkConnection = async () => {
    setServerStatus('checking');
    const result = await testSupabaseConnection();
    setServerStatus(result.ok ? 'online' : 'offline');
  };

  useEffect(() => {
    checkConnection();
  }, []);

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!mobile.match(/^05\d{8}$/)) {
      alert('يرجى إدخال رقم جوال سعودي صحيح (05xxxxxxxx)');
      return;
    }

    setLoading(true);
    const internalEmail = `${mobile}@school.local`;

    try {
      if (isRegistering) {
        if (fullName.trim().split(' ').length < 3) {
          alert('يرجى إدخال الاسم الرباعي كاملاً');
          setLoading(false);
          return;
        }

        const { data: authData, error: authError } = await supabase.auth.signUp({ 
          email: internalEmail, 
          password
        });

        if (authError) throw authError;

        if (authData.user) {
          // إنشاء البروفايل فوراً بعد التسجيل
          const { error: profileError } = await supabase.from('profiles').insert({
            id: authData.user.id,
            full_name: fullName,
            mobile: mobile,
            role: role
          });

          if (profileError) throw profileError;

          if (!authData.session) {
            alert('تم إنشاء الحساب بنجاح. يرجى التواصل مع المدير لتفعيل الدخول (أو تعطيل خيار تأكيد البريد في Supabase)');
            setIsRegistering(false);
          } else {
            onLogin();
          }
        }
      } else {
        const { error } = await supabase.auth.signInWithPassword({ 
          email: internalEmail, 
          password 
        });
        if (error) throw error;
        onLogin();
      }
    } catch (err: any) {
      console.error('Auth Error:', err);
      if (err.message.includes('fetch')) {
        setServerStatus('offline');
        alert('❌ فشل الاتصال بالخادم. تأكد من تفعيل مشروع Supabase.');
      } else {
        alert('تنبيه: ' + err.message);
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-[#f0f4f8] p-4 font-cairo">
      <div className={`w-full ${isRegistering ? 'max-w-2xl' : 'max-w-md'} bg-white rounded-[2.5rem] shadow-2xl overflow-hidden border border-white/50 relative transition-all duration-500`}>

        <div className={`absolute top-0 inset-x-0 h-2 transition-all duration-700 ${
          serverStatus === 'online' ? 'bg-emerald-500' : serverStatus === 'offline' ? 'bg-red-500' : 'bg-amber-400'
        }`} />

        <div className="bg-emerald-900 p-8 text-white text-center relative overflow-hidden">
          <School className="w-16 h-16 mx-auto mb-3 text-emerald-200" />
          <h1 className="text-2xl font-bold font-amiri tracking-wide">ثانوية الأمير عبدالمجيد الأولى</h1>
          <p className="mt-1 text-emerald-200/80 text-xs font-light tracking-widest uppercase">منصة إتقان الرقمية</p>
        </div>

        <div className="p-8">
          <div className="mb-6 text-center">
            <h2 className="text-2xl font-extrabold text-slate-800">
              {isRegistering ? 'إنشاء ملف موظف جديد' : 'تسجيل الدخول'}
            </h2>
          </div>

          <form onSubmit={handleAuth} className="space-y-4">
            {isRegistering && (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4 animate-in fade-in slide-in-from-bottom-2">
                <div className="space-y-4">
                  <div className="relative group">
                    <User className="absolute right-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400 group-focus-within:text-emerald-600 transition-colors" />
                    <input
                      type="text"
                      placeholder="الاسم الرباعي كاملاً"
                      required
                      className="w-full pr-12 pl-4 py-3.5 bg-slate-50 rounded-2xl border border-slate-200 focus:border-emerald-500 focus:ring-4 focus:ring-emerald-500/10 outline-none transition-all"
                      value={fullName}
                      onChange={(e) => setFullName(e.target.value)}
                    />
                  </div>

                  <div className="space-y-2">
                    <label className="text-xs font-bold text-slate-500 mr-2 flex items-center gap-1">
                      <Briefcase className="w-3 h-3" /> اختر المسمى الوظيفي المسند إليك:
                    </label>
                    <div className="grid grid-cols-2 gap-2">
                      {rolesConfig.map((item) => (
                        <button
                          key={item.role}
