import React, { useState } from 'react';
import { Profile } from '../types';
import { CRITERIA_MAP } from '../constants';
import { supabase } from '../supabase';
import { X, Save, AlertCircle, ExternalLink, FileText } from 'lucide-react';

interface Props {
  staff: Profile;
  onClose: () => void;
}

const EvaluationModal: React.FC<Props> = ({ staff, onClose }) => {
  const criteria = CRITERIA_MAP[staff.role];
  const [scores, setScores] = useState<Record<number, number>>({});
  const [comments, setComments] = useState('');
  const [submitting, setSubmitting] = useState(false);

  const calculateTotal = () => {
    const weightedSum = criteria.reduce((sum, c) => {
      const score = scores[c.id] || 0;
      return sum + (score * (c.weight / 100));
    }, 0);
    return Math.round(weightedSum);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (Object.keys(scores).length < criteria.length) {
      alert('يرجى تقييم جميع المعايير');
      return;
    }
    setSubmitting(true);
    const { data: { user } } = await supabase.auth.getUser();
    const { error } = await supabase.from('evaluations').insert({
      staff_id: staff.id,
      evaluator_id: user?.id,
      scores,
      total_score: calculateTotal(),
      comments
    });

    if (error) alert(error.message);
    else {
      alert('تم اعتماد التقييم بنجاح');
      onClose();
    }
    setSubmitting(false);
  };

  return (
    <div className="fixed inset-0 bg-black/70 backdrop-blur-md z-50 flex items-center justify-center p-4">
      <div className="bg-white w-full max-w-5xl max-h-[95vh] rounded-[2.5rem] overflow-hidden flex flex-col shadow-2xl border border-slate-200">

        {/* Header with Drive Link */}
        <div className="p-8 border-b border-slate-100 flex flex-col md:flex-row justify-between items-center bg-slate-50/80 gap-6">
          <div className="text-right">
            <h2 className="text-2xl font-black text-slate-800">تقييم أداء: {staff.full_name}</h2>
            <div className="flex items-center gap-2 mt-1">
              <span className="bg-emerald-100 text-emerald-800 px-3 py-0.5 rounded-full text-[10px] font-bold">{staff.role}</span>
              <span className="text-slate-400 text-[11px] font-medium">| جاري رصد الدرجات للمعيار الوظيفي</span>
            </div>
          </div>

          <div className="flex items-center gap-3 w-full md:w-auto">
            {staff.drive_link ? (
              <a 
                href={staff.drive_link} 
                target="_blank" 
                rel="noopener noreferrer"
                className="flex-1 md:flex-none flex items-center justify-center gap-2 bg-[#0f4c4c] text-white px-6 py-3 rounded-2xl font-bold text-sm shadow-xl shadow-teal-900/20 hover:scale-105 transition-transform"
              >
                <ExternalLink className="w-5 h-5" /> تصفح ملفات الشواهد
              </a>
            ) : (
              <div className="flex-1 md:flex-none flex items-center gap-2 bg-amber-50 text-amber-700 px-5 py-3 rounded-2xl border border-amber-200 text-xs font-bold">
                <AlertCircle className="w-4 h-4" /> الموظف لم يرفع رابط شواهد بعد
              </div>
            )}
            <button onClick={onClose} className="p-3 bg-white hover:bg-red-50 hover:text-red-600 rounded-2xl transition shadow-sm border border-slate-200">
              <X className="w-6 h-6" />
            </button>
          </div>
        </div>

        <div className="flex-1 overflow-auto p-8 bg-slate-50/30">
          <div className="max-w-4xl mx-auto">
            <div className="grid gap-3">
              {criteria.map((c, idx) => (
                <div key={c.id} className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm hover:border-emerald-300 transition-all flex flex-col md:flex-row items-center gap-6">
                  <div className="flex gap-4 flex-1">
                    <div className="bg-slate-100 text-slate-600 w-10 h-10 flex items-center justify-center rounded-xl text-sm font-black shrink-0">
                      {idx + 1}
                    </div>
                    <div className="space-y-1">
                      <p className="text-slate-800 font-bold text-sm leading-relaxed">{c.text}</p>
                      <span className="text-[10px] font-bold text-emerald-600 uppercase tracking-wider">الوزن النسبي لهذا المعيار: {c.weight}%</span>
                    </div>
                  </div>
                  <div className="flex items-center gap-4 w-full md:w-48">
                    <input
                      type="number"
                      min="0"
                      max="100"
                      placeholder="0"
                      className="w-full px-4 py-3 text-center font-black text-lg text-[#0f4c4c] bg-slate-50 border border-slate-200 rounded-xl focus:ring-4 focus:ring-emerald-500/10 focus:border-emerald-500 outline-none transition-all"
                      value={scores[c.id] || ''}
                      onChange={(e) => setScores({ ...scores, [c.id]: Math.min(100, Math.max(0, parseInt(e.target.value) || 0)) })}
                    />
                    <span className="text-[11px] font-bold text-slate-400">/ 100</span>
                  </div>
                </div>
              ))}
            </div>

            <div className="mt-8 space-y-3">
              <label className="flex items-center gap-2 font-black text-slate-700 text-sm mr-2">
                <FileText className="w-4 h-4 text-[#0f4c4c]" /> رأي الخبير التربوي وملاحظات التحسين:
              </label>
              <textarea
                className="w-full px-6 py-4 rounded-3xl border border-slate-200 focus:ring-4 focus:ring-emerald-500/10 focus:border-emerald-500 outline-none h-40 resize-none bg-white text-sm shadow-inner"
                placeholder="اكتب مرئياتك حول أداء الموظف ونقاط القوة والتحسين..."
                value={comments}
                onChange={(e) => setComments(e.target.value)}
              ></textarea>
            </div>
          </div>
        </div>

        <div className="p-8 border-t bg-white flex flex-col md:flex-row justify-between items-center gap-6">
          <div className="flex items-center gap-4">
             <div className="bg-emerald-50 p-3 rounded-2xl">
                <AlertCircle className="w-6 h-6 text-emerald-600" />
             </div>
             <div>
                <p className="text-xs font-bold text-slate-400 uppercase">الدرجة النهائية المستحقة</p>
                <div className="flex items-baseline gap-1">
                  <span className="text-4xl font-black text-[#0f4c4c]">{calculateTotal()}</span>
                  <span className="text-lg font-bold text-slate-400">%</span>
                </div>
             </div>
          </div>
          <button
            onClick={handleSubmit}
            disabled={submitting}
            className="w-full md:w-auto bg-[#0f4c4c] text-white px-12 py-5 rounded-2xl font-black text-lg shadow-2xl shadow-emerald-900/20 hover:bg-[#0d3d3d] active:scale-95 transition-all flex items-center justify-center gap-3 disabled:opacity-50"
          >
            <Save className="w-6 h-6" /> {submitting ? 'جاري الاعتماد...' : 'اعتماد وحفظ التقييم'}
          </button>
        </div>
      </div>
    </div>
  );
};

