      </main>

      {selectedStaff && <EvaluationModal staff={selectedStaff} onClose={() => { setSelectedStaff(null); fetchStaff(); }} />}

      {evaluationToShow && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-xl z-50 flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-5xl h-[95vh] rounded-[3rem] overflow-hidden flex flex-col shadow-2xl border border-white/20">
            <div className="p-6 border-b flex justify-between items-center bg-slate-50 no-print">
              <h2 className="text-xl font-bold font-amiri text-[#0f4c4c]">معاينة بطاقة الأداء الوظيفي</h2>
