            </div>
            <div className="flex-1 overflow-auto bg-slate-100 p-12">
              <PrintableReport staff={evaluationToShow.staff} evaluation={evaluationToShow.evaluation} principalName={userProfile.full_name} />
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const StatusBadge: React.FC<{ staffId: string }> = ({ staffId }) => {
  const [data, setData] = useState<any>(null);
  useEffect(() => {
    supabase.from('evaluations').select('total_score').eq('staff_id', staffId).order('created_at', { ascending: false }).limit(1).single()
      .then(({ data }) => setData(data));
  }, [staffId]);

  return data ? (
    <div className="flex flex-col items-center">
      <span className="bg-emerald-50 text-emerald-700 px-3 py-1 rounded-lg text-[10px] font-black border border-emerald-100 mb-1">تم الاعتماد</span>
      <span className="text-lg font-black text-[#0f4c4c]">{data.total_score}%</span>
    </div>
  ) : (
    <span className="bg-slate-100 text-slate-400 px-3 py-1 rounded-lg text-[10px] font-bold">لم يقيّم بعد</span>
  );
};

const EvaluationActions: React.FC<{ staff: Profile, onShowReport: (ev: any) => void, onShareWhatsApp: (score: number) => void }> = ({ staff, onShowReport, onShareWhatsApp }) => {
  const [evalData, setEvalData] = useState<any>(null);
  useEffect(() => {
    supabase.from('evaluations').select('*').eq('staff_id', staff.id).order('created_at', { ascending: false }).limit(1).single()
      .then(({ data }) => setEvalData(data));
  }, [staff.id]);

  if (!evalData) return null;
  return (
    <div className="flex gap-2">
      <button onClick={() => onShowReport(evalData)} className="p-2.5 text-slate-400 hover:bg-emerald-50 hover:text-[#0f4c4c] rounded-xl transition border border-slate-100" title="طباعة">
        <Printer className="w-4 h-4" />
      </button>
      <button onClick={() => onShareWhatsApp(evalData.total_score)} className="p-2.5 text-emerald-600 hover:bg-emerald-50 rounded-xl transition border border-slate-100" title="واتساب">
        <MessageCircle className="w-4 h-4" />
      </button>
    </div>
  );
};

