        className="p-3 text-slate-400 hover:bg-emerald-50 hover:text-[#0f4c4c] rounded-xl transition-all border border-slate-100" 
        title="معاينة وطباعة"
      >
        <Printer className="w-4 h-4" />
      </button>
      <button 
        onClick={() => onShareWhatsApp(evalData.total_score)} 
        className="p-3 text-emerald-600 hover:bg-emerald-50 rounded-xl transition-all border border-slate-100" 
        title="إرسال عبر واتساب"
      >
        <MessageCircle className="w-4 h-4" />
      </button>
    </div>
  );
};

