          </div>

          {/* Center Side: New Logo and Branding */}
          <div className="flex flex-col items-center gap-2">
            <img 
              src="https://upload.wikimedia.org/wikipedia/ar/archive/e/ed/20180425143048%21Ministry_of_Education_%28Saudi_Abrabia%29_Logo.svg" 
              className="h-20 md:h-24 brightness-0 invert" 
              alt="Logo" 
            />
            <div className="bg-white/10 px-6 py-1 rounded-full border border-white/5 inline-flex items-center gap-2 shadow-inner">
