               <p className="text-[10px] font-bold font-amiri">( بوابة الإدارة - نظام إتقان )</p>
            </div>
          </div>

          {/* Left Side: Logout and Profile Info */}
          <div className="min-w-[220px] flex flex-col items-end gap-3">
             <div className="bg-black/20 px-4 py-1.5 rounded-xl text-[10px] border border-white/5 font-bold">
               <span className="opacity-70">المقيّم: </span>
               <span>{userProfile.full_name}</span>
             </div>
             <button 
                onClick={() => supabase.auth.signOut()} 
