          </div>

        </div>
      </nav>

      <main className="max-w-7xl mx-auto p-6 -mt-8 space-y-6">
        <div className="bg-white p-5 rounded-[2rem] shadow-sm border border-slate-200 flex flex-col md:flex-row gap-4 items-center">
          <div className="relative flex-1 w-full">
            <Search className="absolute right-4 top-3.5 w-5 h-5 text-slate-400" />
