              value={searchTerm} 
              onChange={(e) => setSearchTerm(e.target.value)} 
            />
          </div>
          <select 
            className="w-full md:w-64 px-4 py-3.5 rounded-2xl bg-slate-50 border border-slate-100 outline-none text-sm font-bold text-slate-700 cursor-pointer" 
            value={roleFilter} 
            onChange={(e) => setRoleFilter(e.target.value)}
