                        rel="noopener noreferrer" 
                        className="text-[#0f4c4c] bg-emerald-50 px-3 py-1.5 rounded-lg hover:bg-[#0f4c4c] hover:text-white transition-all flex items-center gap-2 text-[10px] font-black w-fit"
