          <div className="bg-white w-full max-w-5xl h-[95vh] rounded-[3.5rem] overflow-hidden flex flex-col shadow-2xl border border-white/10 animate-in fade-in zoom-in-95 duration-300">
            <div className="p-8 border-b flex justify-between items-center bg-slate-50 no-print">
              <div className="flex items-center gap-4">
                <div className="p-3 bg-[#0f4c4c] text-white rounded-2xl">
                  <Printer className="w-6 h-6" />
                </div>
                <div>
                  <h2 className="text-xl font-black font-amiri text-[#0f4c4c]">معاينة بطاقة الأداء الوظيفي المعتمدة</h2>
                  <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">تأكد من مراجعة البيانات قبل الطباعة النهائية</p>
                </div>
              </div>
              <div className="flex gap-4">
                <button 
                  onClick={() => window.print()} 
                  className="bg-[#0f4c4c] text-white px-10 py-4 rounded-2xl flex items-center gap-3 shadow-2xl shadow-teal-900/20 hover:bg-[#0d3d3d] active:scale-95 transition-all font-black text-sm"
                >
                  <Printer className="w-5 h-5" /> طباعة المستند الرسمي
                </button>
                <button 
                  onClick={() => setEvaluationToShow(null)} 
                  className="bg-white border border-slate-200 text-slate-600 px-8 py-4 rounded-2xl hover:bg-slate-50 active:scale-95 transition-all font-bold text-sm"
