};

const EvaluationActions: React.FC<{ staff: Profile, onShowReport: (ev: any) => void, onShareWhatsApp: (score: number) => void }> = ({ staff, onShowReport, onShareWhatsApp }) => {
  const [evalData, setEvalData] = useState<any>(null);
  useEffect(() => {
    supabase.from('evaluations').select('*').eq('staff_id', staff.id).order('created_at', { ascending: false }).limit(1).single()
