    setLoading(true);
    const { data } = await supabase.from('profiles').select('*').neq('role', UserRole.PRINCIPAL).order('created_at', { ascending: false });
    if (data) setStaff(data);
    setLoading(false);
  };

  const filteredStaff = staff.filter(s => {
    const matchesSearch = s.full_name.includes(searchTerm) || s.mobile.includes(searchTerm);
    const matchesRole = roleFilter === 'all' || s.role === roleFilter;
    return matchesSearch && matchesRole;
  });

  const handleShareWhatsApp = (staff: Profile, score: number) => {
    const formattedScore = score >= 90 ? 'ممتاز' : score >= 80 ? 'جيد جداً' : 'جيد';
    const message = `الأستاذ / ${staff.full_name} المحترم،\n\nنود إبلاغكم بأنه تم اعتماد تقرير الأداء الوظيفي الخاص بكم في ثانوية الأمير عبدالمجيد الأولى.\n\nالنتيجة النهائية: ${score}% (${formattedScore})\n\nيمكنكم الدخول عبر النظام لاستعراض وتحميل التقرير التفصيلي.\n\nمع تمنياتنا لكم بمزيد من العطاء والتميز.\nإدارة المدرسة`;
    window.open(`https://wa.me/966${staff.mobile.substring(1)}?text=${encodeURIComponent(message)}`, '_blank');
  };

  return (
    <div className="min-h-screen bg-[#f8fafc] font-cairo">
      {/* Official Header: Right (Text), Center (Logo/Title), Left (Logout) */}
      <nav className="bg-[#0f4c4c] text-white shadow-xl no-print sticky top-0 z-50 pt-4 pb-12 px-6">
