            <p className="text-[11px] font-bold">المملكة العربية السعودية</p>
            <p className="text-[11px]">وزارة التعليم</p>
            <p className="text-[11px]">الإدارة العامة للتعليم بمحافظة جدة</p>
            <h1 className="text-[14px] font-black border-t border-white/10 mt-1 pt-1 tracking-wide">ثانوية الأمير عبدالمجيد الأولى بجدة</h1>
          </div>

          {/* Center Side: New Logo and Branding */}
          <div className="flex flex-col items-center gap-2">
            <img 
              src="https://up6.cc/2026/01/176840436497671.png" 
              className="h-20 md:h-24" 
              alt="Logo" 
            />
            <div className="bg-white/10 px-6 py-1 rounded-full border border-white/5 inline-flex items-center gap-2 shadow-inner">
               <ShieldCheck className="w-3 h-3 text-emerald-400" />
               <p className="text-[10px] font-bold">( بوابة الإدارة - نظام إتقان )</p>
            </div>
          </div>

          {/* Left Side: Logout and Profile Info */}
          <div className="min-w-[220px] flex flex-col items-end gap-3">
             <div className="bg-black/20 px-4 py-1.5 rounded-xl text-[10px] border border-white/5 font-bold">
               <span className="opacity-70">المقيّم: </span>
               <span>{userProfile.full_name}</span>
             </div>
             <button 
                onClick={() => supabase.auth.signOut()} 
                className="bg-red-500/10 hover:bg-red-500/20 text-red-200 px-5 py-2 rounded-xl transition-all border border-red-500/20 text-xs flex items-center gap-2 group font-bold"
              >
                تسجيل الخروج
                <LogOut className="w-4 h-4 group-hover:translate-x-1 transition-transform" />
              </button>
          </div>

        </div>
      </nav>

      <main className="max-w-7xl mx-auto p-6 -mt-8 space-y-6">
        <div className="bg-white p-5 rounded-[2rem] shadow-sm border border-slate-200 flex flex-col md:flex-row gap-4 items-center">
          <div className="relative flex-1 w-full">
            <Search className="absolute right-4 top-3.5 w-5 h-5 text-slate-400" />
            <input 
              type="text" 
              placeholder="البحث باسم الموظف أو رقم الجوال..." 
              className="w-full pr-12 pl-4 py-3.5 rounded-2xl bg-slate-50 border border-slate-100 focus:border-[#0f4c4c] outline-none text-sm transition-all" 
              value={searchTerm} 
              onChange={(e) => setSearchTerm(e.target.value)} 
            />
          </div>
          <select 
            className="w-full md:w-64 px-4 py-3.5 rounded-2xl bg-slate-50 border border-slate-100 outline-none text-sm font-bold text-slate-700 cursor-pointer" 
            value={roleFilter} 
            onChange={(e) => setRoleFilter(e.target.value)}
          >
            <option value="all">جميع الفئات الوظيفية</option>
            {Object.values(UserRole).filter(r => r !== UserRole.PRINCIPAL).map(r => <option key={r} value={r}>{r}</option>)}
          </select>
        </div>

        <div className="bg-white rounded-[2.5rem] shadow-sm border border-slate-200 overflow-hidden transition-all hover:shadow-md">
          <table className="w-full text-right">
            <thead className="bg-slate-50/50 text-slate-500 text-[11px] font-black uppercase tracking-widest">
              <tr>
                <th className="px-8 py-6">بيانات المنسوب</th>
                <th className="px-8 py-6">المسمى الوظيفي</th>
                <th className="px-8 py-6">رابط الشواهد</th>
                <th className="px-8 py-6 text-center">الحالة والدرجة</th>
                <th className="px-8 py-6 text-center">العمليات المتاحة</th>
