            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredStaff.map((s) => (
                <tr key={s.id} className="hover:bg-slate-50/50 transition-colors group">
                  <td className="px-8 py-6">
                    <div className="font-bold text-slate-800 group-hover:text-[#0f4c4c] transition-colors">{s.full_name}</div>
                    <div className="text-[10px] text-slate-400 font-sans tracking-wider mt-0.5">{s.mobile}</div>
                  </td>
                  <td className="px-8 py-6 text-sm font-medium text-slate-600 italic">{s.role}</td>
                  <td className="px-8 py-6">
                    {s.drive_link ? (
                      <a 
                        href={s.drive_link} 
                        target="_blank" 
                        rel="noopener noreferrer" 
                        className="text-[#0f4c4c] bg-emerald-50 px-3 py-1.5 rounded-lg hover:bg-[#0f4c4c] hover:text-white transition-all flex items-center gap-2 text-[10px] font-black w-fit"
                      >
