                >
                  <Printer className="w-5 h-5" /> طباعة المستند الرسمي
                </button>
                <button 
                  onClick={() => setEvaluationToShow(null)} 
                  className="bg-white border border-slate-200 text-slate-600 px-8 py-4 rounded-2xl hover:bg-slate-50 active:scale-95 transition-all font-bold text-sm"
                >
                  إلغاء المعاينة
                </button>
              </div>
            </div>
            <div className="flex-1 overflow-auto bg-slate-200/50 p-12">
              <div className="bg-white shadow-2xl rounded-sm mx-auto p-4 scale-95 origin-top">
                <PrintableReport staff={evaluationToShow.staff} evaluation={evaluationToShow.evaluation} principalName={userProfile.full_name} />
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const StatusBadge: React.FC<{ staffId: string }> = ({ staffId }) => {
  const [data, setData] = useState<any>(null);
  useEffect(() => {
    supabase.from('evaluations').select('total_score').eq('staff_id', staffId).order('created_at', { ascending: false }).limit(1).single()
      .then(({ data }) => setData(data));
  }, [staffId]);

  return data ? (
    <div className="flex flex-col items-center">
      <span className="bg-emerald-50 text-emerald-700 px-3 py-1 rounded-lg text-[9px] font-black border border-emerald-100 mb-1">تم الاعتماد</span>
      <div className="flex items-baseline gap-0.5">
        <span className="text-xl font-black text-[#0f4c4c]">{data.total_score}</span>
        <span className="text-[10px] font-bold text-slate-400">%</span>
      </div>
    </div>
  ) : (
    <span className="bg-slate-100 text-slate-400 px-3 py-1.5 rounded-lg text-[9px] font-bold">لم يقيّم</span>
  );
};

const EvaluationActions: React.FC<{ staff: Profile, onShowReport: (ev: any) => void, onShareWhatsApp: (score: number) => void }> = ({ staff, onShowReport, onShareWhatsApp }) => {
  const [evalData, setEvalData] = useState<any>(null);
  useEffect(() => {
    supabase.from('evaluations').select('*').eq('staff_id', staff.id).order('created_at', { ascending: false }).limit(1).single()
      .then(({ data }) => setEvalData(data));
  }, [staff.id]);

  if (!evalData) return null;
  return (
    <div className="flex gap-2">
      <button 
        onClick={() => onShowReport(evalData)} 
        className="p-3 text-slate-400 hover:bg-emerald-50 hover:text-[#0f4c4c] rounded-xl transition-all border border-slate-100" 
        title="معاينة وطباعة"
      >
        <Printer className="w-4 h-4" />
      </button>
      <button 
        onClick={() => onShareWhatsApp(evalData.total_score)} 
