    window.open(`https://wa.me/966${staff.mobile.substring(1)}?text=${encodeURIComponent(message)}`, '_blank');
  };

  return (
    <div className="min-h-screen bg-[#f8fafc] font-cairo">
      {/* Official Header: Right (Text), Center (Logo/Title), Left (Logout) */}
