const StatusBadge: React.FC<{ staffId: string }> = ({ staffId }) => {
  const [data, setData] = useState<any>(null);
  useEffect(() => {
    supabase.from('evaluations').select('total_score').eq('staff_id', staffId).order('created_at', { ascending: false }).limit(1).single()
      .then(({ data }) => setData(data));
  }, [staffId]);

  return data ? (
    <div className="flex flex-col items-center">
      <span className="bg-emerald-100 text-emerald-800 px-4 py-1.5 rounded-full text-[10px] font-black border border-emerald-200 mb-2">معتمد</span>
      <div className="flex items-baseline gap-1">
        <span className="text-2xl font-black text-[#0f4c4c]">{data.total_score}</span>
        <span className="text-xs font-black text-slate-300">%</span>
      </div>
    </div>
  ) : (
    <span className="bg-slate-50 text-slate-300 px-5 py-2.5 rounded-[1.5rem] text-[10px] font-black border border-slate-100">شاغر</span>
  );
};

const EvaluationActions: React.FC<{ staff: Profile, onShowReport: (ev: any) => void, onShareWhatsApp: (score: number) => void }> = ({ staff, onShowReport, onShareWhatsApp }) => {
  const [evalData, setEvalData] = useState<any>(null);
  useEffect(() => {
    supabase.from('evaluations').select('*').eq('staff_id', staff.id).order('created_at', { ascending: false }).limit(1).single()
      .then(({ data }) => setEvalData(data));
  }, [staff.id]);

  if (!evalData) return null;
  return (
    <div className="flex gap-3">
      <button onClick={() => onShowReport(evalData)} className="p-4 text-slate-400 hover:bg-emerald-50 hover:text-[#0f4c4c] rounded-2xl transition-all border border-slate-100 hover:border-emerald-200" title="طباعة">
        <Printer className="w-5 h-5" />
      </button>
      <button onClick={() => onShareWhatsApp(evalData.total_score)} className="p-4 text-emerald-600 hover:bg-emerald-50 rounded-2xl transition-all border border-slate-100 hover:border-emerald-200" title="واتساب">
        <MessageCircle className="w-5 h-5" />
      </button>
    </div>
  );
};

