import React, { useState, useEffect } from 'react';
import { Profile, Evaluation } from '../types';
import { CRITERIA_MAP } from '../constants';
import { supabase } from '../supabase';
import { 
  X, Save, AlertCircle, ExternalLink, 
  FileText, Star, ClipboardCheck, 
  CheckCircle2, Info, ArrowUpRight
} from 'lucide-react';

interface Props {
  staff: Profile;
  onClose: () => void;
}

const EvaluationModal: React.FC<Props> = ({ staff, onClose }) => {
  const criteria = CRITERIA_MAP[staff.role] || [];
  const [scores, setScores] = useState<Record<number, number>>({});
  const [comments, setComments] = useState('');
  const [submitting, setSubmitting] = useState(false);

  useEffect(() => {
    const fetchOldEval = async () => {
      const { data } = await supabase
        .from('evaluations')
        .select('*')
        .eq('staff_id', staff.id)
        .order('created_at', { ascending: false })
        .limit(1)
        .single();
      if (data) {
        setScores(data.scores);
        setComments(data.comments || '');
      }
    };
    fetchOldEval();
  }, [staff.id]);

  const calculateTotal = () => {
    // الدرجة النهائية هي مجموع الدرجات المدخلة (بما أن مجموع الأوزان = 100)
    const sum = Object.values(scores).reduce((acc, score) => acc + (score || 0), 0);
    return Math.min(100, Math.round(sum));
  };

  const getGrade = (score: number) => {
    if (score >= 90) return 'ممتاز';
    if (score >= 80) return 'جيد جداً';
    if (score >= 70) return 'جيد';
    return 'مرضي';
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (Object.keys(scores).length < criteria.length) {
      alert('الرجاء تعبئة درجات جميع المعايير قبل الاعتماد');
      return;
    }
    setSubmitting(true);
    const { data: { user } } = await supabase.auth.getUser();

    const { error } = await supabase.from('evaluations').upsert({
      staff_id: staff.id,
      evaluator_id: user?.id,
      scores,
      total_score: calculateTotal(),
      comments
    }, { onConflict: 'staff_id' });

    if (error) alert(error.message);
    else {
      alert('تم رصد واعتماد التقييم بنجاح');
      onClose();
    }
    setSubmitting(false);
  };

  return (
    <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-xl z-[100] flex items-center justify-center p-4">
      <div className="bg-white w-full max-w-[1200px] max-h-[95vh] rounded-[4rem] overflow-hidden flex flex-col shadow-2xl animate-in zoom-in-95 duration-300">

        {/* Header - Styled like the screenshot */}
        <div className="p-10 border-b border-slate-100 flex flex-col md:flex-row justify-between items-start gap-6 bg-white">
          <div className="flex items-center gap-6">
             <button onClick={onClose} className="p-4 bg-slate-50 text-slate-400 hover:text-red-500 rounded-3xl transition-all border border-slate-100">
               <X className="w-6 h-6" />
             </button>
             {staff.drive_link && (
               <a href={staff.drive_link} target="_blank" className="bg-[#00a18e] text-white px-8 py-4 rounded-[1.5rem] font-black text-xs flex items-center gap-3 shadow-xl shadow-emerald-900/10 hover:scale-105 transition-all">
                 <ExternalLink className="w-5 h-5" /> فحص ملفات الشواهد
               </a>
             )}
          </div>

          <div className="text-right flex items-center gap-6">
             <div className="space-y-1">
                <div className="flex items-center justify-end gap-3">
                   <h2 className="text-3xl font-black text-slate-800 font-official">تقييم أداء: {staff.full_name}</h2>
                </div>
                <div className="flex items-center justify-end gap-3">
                   <span className="text-slate-400 text-xs font-bold">معايير الدليل الإجرائي المعتمد</span>
                   <span className="bg-[#0f4c4c] text-white px-4 py-1.5 rounded-full text-[10px] font-black">{staff.role}</span>
                </div>
             </div>
             <div className="w-16 h-16 bg-white rounded-[2rem] shadow-xl flex items-center justify-center border border-slate-50">
                <Star className="w-8 h-8 text-[#0f4c4c]" />
             </div>
          </div>
        </div>

        {/* Content - 2 Column Cards Grid */}
        <div className="flex-1 overflow-auto p-12 bg-slate-50/30">
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
            {criteria.map((c, idx) => (
              <div key={c.id} className="bg-white p-8 rounded-[3rem] border border-slate-100 shadow-sm hover:shadow-xl transition-all group flex flex-col gap-6 relative overflow-hidden">
                <div className="flex justify-between items-start">
                   <div className="w-12 h-12 bg-slate-50 text-slate-400 rounded-2xl flex items-center justify-center font-black text-sm group-hover:bg-[#0f4c4c] group-hover:text-white transition-colors">
                     {idx + 1}
                   </div>
                   <div className="text-right space-y-1">
                      <p className="text-slate-700 font-black text-base leading-snug">{c.text}</p>
                      <div className="flex items-center justify-end gap-3">
                         <span className="text-[10px] font-black text-emerald-500">الحد الأقصى: {c.weight}</span>
                         <span className="text-[10px] font-black text-slate-300">الوزن النسبي: {c.weight}%</span>
                      </div>
                   </div>
                </div>

                <div className="relative group/input">
                  <div className="absolute right-6 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within/input:text-[#00a18e] transition-colors">
                    <ClipboardCheck className="w-6 h-6" />
                  </div>
                  <input
                    type="number"
                    step="0.5"
                    min="0"
                    max={c.weight}
                    placeholder={`أدخل الدرجة (بحد أقصى ${c.weight})`}
                    className="w-full pr-16 pl-8 py-5 rounded-[2rem] bg-slate-50 border border-slate-100 focus:bg-white focus:border-[#00a18e] outline-none text-center font-black text-xl text-[#0f4c4c] font-sans transition-all shadow-inner"
                    value={scores[c.id] || ''}
                    onChange={(e) => {
                      const val = parseFloat(e.target.value) || 0;
                      // منع إدخال قيمة تتجاوز الوزن
                      const safeVal = Math.min(c.weight, Math.max(0, val));
                      setScores({ ...scores, [c.id]: safeVal });
                    }}
                  />
                  {/* Visual Indicator of completion */}
                  {scores[c.id] !== undefined && (
                    <div className="absolute left-6 top-1/2 -translate-y-1/2">
                       <div className={`w-3 h-3 rounded-full ${scores[c.id] > 0 ? 'bg-emerald-500 animate-pulse' : 'bg-slate-200'}`}></div>
                    </div>
                  )}
                </div>
              </div>
            ))}
          </div>

          <div className="mt-12 space-y-4 max-w-4xl mx-auto">
             <label className="flex items-center gap-3 font-black text-slate-600 text-sm px-6">
                <FileText className="w-5 h-5 text-[#0f4c4c]" /> التوصيات والملاحظات الإدارية
             </label>
             <textarea
               className="w-full px-10 py-8 rounded-[3rem] border border-slate-200 focus:border-[#0f4c4c] outline-none h-40 resize-none bg-white text-base shadow-inner transition-all leading-relaxed font-bold"
               placeholder="اكتب مرئياتك حول أداء الموظف هنا..."
               value={comments}
               onChange={(e) => setComments(e.target.value)}
             ></textarea>
          </div>
        </div>

        {/* Footer - Bottom Bar styled like the screenshot */}
        <div className="p-10 border-t bg-white flex flex-col md:flex-row justify-between items-center gap-10">

          <button
            onClick={handleSubmit}
            disabled={submitting}
            className="w-full md:w-auto bg-[#0f4c4c] text-white px-16 py-6 rounded-[2.5rem] font-black text-xl shadow-2xl shadow-teal-900/20 hover:bg-[#0d3d3d] hover:scale-105 active:scale-95 transition-all flex items-center justify-center gap-4 disabled:opacity-50"
          >
            {submitting ? 'جاري الاعتماد...' : 'اعتماد التقييم النهائي وحفظ البيانات'}
            {!submitting && <Save className="w-6 h-6" />}
          </button>

          <div className="flex items-center gap-8">
             <div className="text-right">
                <p className="text-[11px] font-black text-slate-400 uppercase tracking-widest mb-1">إجمالي درجة الأداء الحالية</p>
                <div className="flex items-center justify-end gap-3">
                   <h4 className="text-4xl font-black text-slate-800 font-official">{getGrade(calculateTotal())}</h4>
                   <CheckCircle2 className="w-6 h-6 text-emerald-500" />
                </div>
             </div>

             {/* Progress Circle - Matched to Image */}
             <div className="relative w-24 h-24 flex items-center justify-center shrink-0">
                <svg className="w-full h-full -rotate-90">
                   <circle cx="48" cy="48" r="42" stroke="currentColor" strokeWidth="10" fill="transparent" className="text-slate-100" />
                   <circle cx="48" cy="48" r="42" stroke="currentColor" strokeWidth="10" fill="transparent" strokeDasharray={264} strokeDashoffset={264 - (264 * calculateTotal()) / 100} className="text-[#0f4c4c] transition-all duration-1000" strokeLinecap="round" />
                </svg>
                <div className="absolute inset-0 flex items-center justify-center">
                   <span className="text-3xl font-black text-[#0f4c4c] font-sans">{calculateTotal()}</span>
                </div>
             </div>
          </div>

        </div>
      </div>
    </div>
  );
};

