    const sum = (Object.values(scores) as number[]).reduce((acc: number, score: number) => acc + (score || 0), 0);
    return Math.min(100, Math.round(sum));
  };

  const getGradeInfo = (score: number) => {
    if (score >= 90) return { label: 'ممتاز', rating: '5/5', desc: 'أداء يفوق التوقعات بشكل استثنائي', color: 'text-emerald-600', bg: 'bg-emerald-50' };
