    if (score >= 90) return { label: 'ممتاز', rating: '(5/5)', color: 'text-emerald-600', bg: 'bg-emerald-600' };
    if (score >= 80) return { label: 'جيد جداً', rating: '(4/5)', color: 'text-blue-600', bg: 'bg-blue-600' };
    if (score >= 70) return { label: 'جيد', rating: '(3/5)', color: 'text-amber-600', bg: 'bg-amber-600' };
    if (score >= 60) return { label: 'مرضي', rating: '(2/5)', color: 'text-orange-600', bg: 'bg-orange-600' };
    return { label: 'غير مرضي', rating: '(1/5)', color: 'text-red-600', bg: 'bg-red-600' };
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (Object.keys(ratings).length < criteria.length) {
      alert('الرجاء تعبئة كافة بنود التقييم قبل الحفظ');
      return;
    }
    setSubmitting(true);
    const { data: { user } } = await supabase.auth.getUser();

    // تحويل التقييمات (1-5) إلى نقاط فعلية (بناءً على الوزن)
    const scores: Record<number, number> = {};
    Object.entries(ratings).forEach(([id, rating]) => {
      // Added explicit cast to number to fix TS error on line 85
      scores[Number(id)] = calculateScoreForCriterion(Number(id), rating as number);
    });

    const payload: any = {
      staff_id: staff.id,
      evaluator_id: user?.id,
      scores,
      total_score: calculateTotal(),
      comments
    };

    if (existingEvalId) payload.id = existingEvalId;

    const { error } = await supabase.from('evaluations').upsert(payload);

    if (error) {
      alert('خطأ أثناء الحفظ: ' + error.message);
    } else {
      alert('تم اعتماد التقييم بنجاح وفق سلم التقدير المعتمد');
      onClose();
    }
    setSubmitting(false);
  };

  const totalScore = calculateTotal();
