                  <th className="px-6 py-4 text-sm font-black w-72 text-center">سلم التقدير (1-5)</th>
                </tr>
              </thead>
              <tbody>
                {criteria.map((c, idx) => {
                  // UserRole is now correctly imported to resolve line 154 error
