interface Props {
  staff: Profile;
  evaluation: Evaluation;
  principalName: string;
}

const PrintableReport: React.FC<Props> = ({ staff, evaluation, principalName }) => {
  const criteria = CRITERIA_MAP[staff.role];

  const getGradeInfo = (score: number) => {
    if (score >= 90) return { label: 'ممتاز', rating: '(5/5)' };
    if (score >= 80) return { label: 'جيد جداً', rating: '(4/5)' };
    if (score >= 70) return { label: 'جيد', rating: '(3/5)' };
    if (score >= 60) return { label: 'مرضي', rating: '(2/5)' };
    return { label: 'غير مرضي', rating: '(1/5)' };
  };

  const gradeInfo = getGradeInfo(evaluation.total_score);

  return (
