const Dashboard: React.FC<{ userProfile: Profile }> = ({ userProfile }) => {
  const [driveLink, setDriveLink] = useState(userProfile.drive_link || '');
  const [driveLinkV2, setDriveLinkV2] = useState(userProfile.drive_link_v2 || '');
  const [saving, setSaving] = useState(false);
  const [lastEval, setLastEval] = useState<Evaluation | null>(null);
  const [currentProfile, setCurrentProfile] = useState<Profile>(userProfile);

  useEffect(() => {
    fetchLatestEvaluation();
  }, []);

  const fetchLatestEvaluation = async () => {
    const { data: evalData } = await supabase
      .from('evaluations')
      .select('*')
      .eq('staff_id', userProfile.id)
      .order('created_at', { ascending: false })
      .limit(1)
      .single();
    if (evalData) setLastEval(evalData);

    const { data: profileData } = await supabase
      .from('profiles')
      .select('*')
      .eq('id', userProfile.id)
      .single();
    if (profileData) {
      setCurrentProfile(profileData);
      setDriveLink(profileData.drive_link || '');
      setDriveLinkV2(profileData.drive_link_v2 || '');
    }
  };

  // دالة النقاط الصحيحة (78 -> 3)
  const getGradeInfo = (score: number) => {
    let points = 1;
    let label = 'غير مرضي';
    let color = 'text-red-600';
    let bg = 'bg-red-600';
    let border = 'border-red-100';

    if (score >= 90) { points = 5; label = 'ممتاز'; color = 'text-emerald-600'; bg = 'bg-emerald-600'; border = 'border-emerald-100'; }
    else if (score >= 80) { points = 4; label = 'جيد جداً'; color = 'text-blue-600'; bg = 'bg-blue-600'; border = 'border-blue-100'; }
    else if (score >= 70) { points = 3; label = 'جيد'; color = 'text-amber-600'; bg = 'bg-amber-600'; border = 'border-amber-100'; }
    else if (score >= 60) { points = 2; label = 'مرضي'; color = 'text-orange-600'; bg = 'bg-orange-600'; border = 'border-orange-100'; }

    return { label, points, color, bg, border };
  };

  const handleUpdateLink = async (isV2: boolean) => {
    setSaving(true);
    const updateData = isV2 ? { drive_link_v2: driveLinkV2 } : { drive_link: driveLink };
    const { error } = await supabase
      .from('profiles')
      .update(updateData)
      .eq('id', userProfile.id);

    if (error) alert(error.message);
    else {
      alert('تم تحديث الرابط بنجاح. سيتم إخطار الإدارة.');
      fetchLatestEvaluation();
    }
    setSaving(false);
  };

  const grade = lastEval ? getGradeInfo(lastEval.total_score) : null;

  return (
    <div className="min-h-screen bg-[#f4f7f6] pb-20 font-cairo text-right" dir="rtl">
