           <div className="text-right space-y-0.5">
              <p className="text-sm font-bold">المملكة العربية السعودية</p>
              <p className="text-sm">وزارة التعليم</p>
              <p className="text-lg font-black mt-2 text-white border-r-4 border-[#00a18e] pr-4">ثانوية الأمير عبدالمجيد الأولى</p>
           </div>
           <div className="absolute left-1/2 -translate-x-1/2 flex flex-col items-center gap-3">
              <img src="https://up6.cc/2026/01/176840436497671.png" className="h-28 object-contain drop-shadow-xl" alt="Logo" />
           </div>
           <button onClick={() => supabase.auth.signOut()} className="bg-white/10 px-6 py-2 rounded-xl text-xs hover:bg-red-500/20 transition-all flex items-center gap-2 font-black">
              تسجيل خروج <LogOut className="w-4 h-4" />
           </button>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-6 -mt-10 space-y-8 relative z-20">
        {/* ملخص الأداء بنظام النقاط الصحيحة */}
        {lastEval && (
          <div className="bg-white rounded-[3rem] p-10 shadow-2xl border-2 border-[#0f4c4c]/10 flex flex-col md:flex-row items-center gap-10">
             <div className="relative w-32 h-32 flex items-center justify-center">
                <svg className="w-full h-full -rotate-90">
                   <circle cx="64" cy="64" r="58" stroke="currentColor" strokeWidth="10" fill="transparent" className="text-slate-100" />
                   <circle cx="64" cy="64" r="58" stroke="currentColor" strokeWidth="10" fill="transparent" strokeDasharray={364} strokeDashoffset={364 - (364 * lastEval.total_score) / 100} className={`${grade?.color.replace('text-', 'stroke-')} transition-all duration-1000`} strokeLinecap="round" />
                </svg>
                <div className="absolute flex flex-col items-center">
                   <span className="text-4xl font-black text-[#0f4c4c] font-sans">{grade?.points}</span>
                   <span className="text-[10px] font-bold text-slate-400">من 5</span>
                </div>
             </div>
             <div className="flex-1 text-center md:text-right">
                <div className="flex items-center gap-3 mb-2 justify-center md:justify-start">
                   <h2 className={`text-3xl font-black ${grade?.color}`}>مستوى الأداء: {grade?.label}</h2>
                   <span className="bg-slate-100 px-4 py-1 rounded-full text-xs font-bold text-slate-500">{lastEval.total_score}%</span>
                </div>
                <p className="text-slate-600 font-medium leading-relaxed max-w-2xl">بناءً على التقييم الأخير بتاريخ {new Date(lastEval.created_at).toLocaleDateString('ar-SA')}، يمكنك الآن تحسين ملفك إذا لم تكن راضياً عن النتيجة عبر قسم "مجلد التحسين" أدناه.</p>
             </div>
             <div className="bg-emerald-50 p-6 rounded-[2rem] border border-emerald-100 text-center min-w-[180px]">
                <ShieldCheck className="w-8 h-8 text-emerald-600 mx-auto mb-2" />
