                <p className="text-lg font-black text-emerald-600">مكتمل</p>
             </div>
          </div>
        )}

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          {/* المجلد الأول (الأساسي) */}
          <div className={`bg-white p-8 rounded-[3rem] shadow-xl border border-slate-200 relative ${lastEval ? 'opacity-70 pointer-events-none' : ''}`}>
             <div className="flex justify-between items-center mb-6">
                <div className="bg-slate-100 p-3 rounded-2xl"><LinkIcon className="text-slate-500" /></div>
                <span className="text-[10px] font-bold bg-slate-100 px-3 py-1 rounded-full">المجلد الأساسي</span>
             </div>
             <h3 className="text-xl font-black mb-4">رابط الشواهد الأول</h3>
             <input type="url" disabled={!!lastEval} value={driveLink} onChange={(e) => setDriveLink(e.target.value)} placeholder="رابط Google Drive..." className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl outline-none font-sans text-xs dir-ltr mb-4" />
