            </button>
          </form>
          <button onClick={() => setIsRegistering(!isRegistering)} className="w-full mt-6 text-[#0f4c4c] font-bold text-xs hover:underline font-cairo">
            {isRegistering ? 'لديك حساب؟ سجل دخولك' : 'مستخدم جديد؟ سجل بياناتك الآن'}
          </button>
        </div>
      </div>
    </div>
  );
};

