    const payload: any = {
      staff_id: staff.id,
      evaluator_id: user?.id,
      scores: ratings, // نخزن التقديرات الخام (1-5)
      total_score: finalPercentage,
      comments
    };

    if (existingEvalId) payload.id = existingEvalId;

    const { error } = await supabase.from('evaluations').upsert(payload);

