             <input type="url" disabled={!!lastEval} value={driveLink} onChange={(e) => setDriveLink(e.target.value)} placeholder="رابط Google Drive..." className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl outline-none font-sans text-xs dir-ltr mb-4" />
             {!lastEval && (
               <button onClick={() => handleUpdateLink(false)} disabled={saving} className="w-full bg-[#0f4c4c] text-white py-3 rounded-2xl font-black flex items-center justify-center gap-2 hover:bg-black transition-all shadow-lg active:scale-95">
                 <Send className="w-4 h-4" /> اعتماد المجلد
               </button>
             )}
             {lastEval && <div className="text-[10px] text-slate-400 font-bold flex items-center justify-center gap-2 py-2"><Lock className="w-3 h-3" /> تم القفل بعد التقييم</div>}
          </div>

          <div className={`bg-white p-6 rounded-[2.5rem] shadow-xl border-2 border-emerald-500 relative overflow-hidden ${!lastEval ? 'opacity-30 grayscale pointer-events-none' : ''}`}>
             <div className="flex justify-between items-center mb-4">
                <div className="bg-emerald-50 p-2 rounded-xl"><Sparkles className="text-emerald-500 w-5 h-5" /></div>
                <span className="text-[9px] font-black bg-emerald-100 text-emerald-700 px-3 py-1 rounded-full uppercase tracking-tighter">تحسين الأداء</span>
             </div>
             <input type="url" value={driveLinkV2} onChange={(e) => setDriveLinkV2(e.target.value)} placeholder="رابط المجلد الجديد (بعد التحسين)..." className="w-full p-4 bg-emerald-50 border border-emerald-200 rounded-2xl outline-none font-sans text-xs dir-ltr mb-4" />
             <button onClick={() => handleUpdateLink(true)} disabled={saving} className="w-full bg-emerald-600 text-white py-3 rounded-2xl font-black flex items-center justify-center gap-2 hover:bg-emerald-700 transition-all shadow-lg active:scale-95">
                <ChevronLeft className="w-4 h-4" /> إرسال نسخة المراجعة
             </button>
          </div>
        </div>

        {/* الملحوظات */}
        {lastEval && (
          <div className="bg-[#0f4c4c] p-6 rounded-[2.5rem] text-white shadow-xl flex items-center gap-5 border-4 border-white/5">
             <div className="bg-white/10 p-3 rounded-2xl flex-shrink-0">
                <Lightbulb className="w-6 h-6 text-emerald-400" />
             </div>
             <div className="flex-1">
                <p className="text-[10px] font-bold opacity-60 mb-1 tracking-widest uppercase">توصيات القيادة المدرسية:</p>
                <p className="text-sm font-black italic">"{lastEval.comments || 'نثمن جهودكم المهنية المتميزة، وننصح بالاستمرار على هذا النهج التطويري.'}"</p>
             </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect } from 'react';
import { supabase } from '../supabase';
import { Profile, UserRole, Evaluation } from '../types';
import { 
  Search, LogOut, Printer, 
  MessageCircle, ShieldCheck, Settings, Sparkles,
  Users, CheckCircle, Clock, FileSearch, UserCheck, X, AlertCircle,
  UserPlus, UserMinus, ShieldAlert, Check, Loader2, AlertTriangle
} from 'lucide-react';
import EvaluationModal from './EvaluationModal';
import PrintableReport from './PrintableReport';

const PrincipalDashboard: React.FC<{ userProfile: Profile }> = ({ userProfile }) => {
  const [staff, setStaff] = useState<Profile[]>([]);
  const [evaluations, setEvaluations] = useState<Record<string, Evaluation>>({});
  const [loading, setLoading] = useState(true);
  const [processingId, setProcessingId] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [view, setView] = useState<'active' | 'pending'>('active');
  const [selectedStaff, setSelectedStaff] = useState<Profile | null>(null);
  const [evaluationToShow, setEvaluationToShow] = useState<any>(null);

  useEffect(() => { fetchData(); }, []);

  const fetchData = async () => {
    setLoading(true);
    try {
      const { data: staffData, error: fetchError } = await supabase
        .from('profiles')
        .select('*')
        .neq('role', UserRole.PRINCIPAL)
        .order('created_at', { ascending: false });

      if (fetchError) {
        console.error(fetchError);
      }

      const { data: evalData } = await supabase.from('evaluations').select('*');

      if (staffData) setStaff(staffData);
      if (evalData) {
        const evalMap = evalData.reduce((acc: any, curr: Evaluation) => {
          acc[curr.staff_id] = curr;
          return acc;
        }, {});
        setEvaluations(evalMap);
      }
    } catch (e) {
      console.error("Fetch error:", e);
    } finally {
      setLoading(false);
    }
  };

  const approveUser = async (id: string) => {
    if (!confirm('هل أنت متأكد من اعتماد هذا الحساب؟')) return;
    setProcessingId(id);
    const { error } = await supabase.from('profiles').update({ is_approved: true }).eq('id', id);
    if (error) alert(error.message);
    else setStaff(prev => prev.map(s => s.id === id ? { ...s, is_approved: true } : s));
    setProcessingId(null);
  };

  const deleteUser = async (id: string) => {
    if (!confirm('سيتم حذف طلب هذا المستخدم نهائياً. هل أنت متأكد؟')) return;
    setProcessingId(id);
    const { error } = await supabase.from('profiles').delete().eq('id', id);
    if (error) alert(error.message);
    else {
      setStaff(prev => prev.filter(s => s.id !== id));
      alert('تم الحذف. يرجى ملاحظة: يجب عليك أيضاً حذف البريد الإلكتروني لهذا الرقم من قسم Authentication في Supabase ليتمكن الموظف من التسجيل من جديد.');
    }
    setProcessingId(null);
  };

  const isArabicMobile = (mobile: string) => /[٠-٩]/.test(mobile);

  const activeStaff = staff.filter(s => s.is_approved && (s.full_name.includes(searchTerm) || s.mobile.includes(searchTerm)));
  const pendingStaff = staff.filter(s => !s.is_approved);

  const getGradeInfo = (score: number) => {
    let points = 1; let label = 'غير مرضي';
    if (score >= 90) { points = 5; label = 'مثالي'; }
    else if (score >= 80) { points = 4; label = 'تخطى التوقعات'; }
    else if (score >= 70) { points = 3; label = 'وافق التوقعات'; }
    else if (score >= 60) { points = 2; label = 'بحاجة إلى تطوير'; }
    return { label, points };
  };

  const handlePrint = (s: Profile, ev: Evaluation) => {
    setEvaluationToShow({ staff: s, evaluation: ev });
    setTimeout(() => { window.print(); setEvaluationToShow(null); }, 500);
  };

  const openWhatsApp = (s: Profile, ev?: Evaluation) => {
    const mobile = s.mobile;
    const formatted = mobile.startsWith('0') ? '966' + mobile.substring(1) : mobile;
    let message = `الأستاذ / ${s.full_name}%0A`;
    if (ev) {
      const info = getGradeInfo(ev.total_score);
      message += `لقد تم رصد تقييمك للأداء الوظيفي بنجاح:%0A`;
      message += `النتيجة المئوية: ${ev.total_score}%%0A`;
      message += `التقدير: ${info.label}%0A%0A`;
    } else {
      message += `نأمل التكرم بتجهيز ملف الشواهد الرقمي الخاص بكم عبر المنصة.%0A%0A`;
    }
    message += `مدير المدرسة: ${userProfile.full_name}`;
    window.open(`https://wa.me/${formatted}?text=${message}`, '_blank');
  };

  return (
    <div className="min-h-screen bg-[#f8fafc] font-cairo text-right" dir="rtl">
      <header className="bg-[#0f4c4c] text-white pt-8 pb-20 px-6 relative overflow-hidden shadow-2xl no-print">
        <div className="max-w-7xl mx-auto flex flex-col md:flex-row justify-between items-center gap-6 relative z-10">
           <div className="text-right space-y-0.5 order-2 md:order-1 flex-1">
              <p className="text-[10px] md:text-xs font-bold opacity-90">المملكة العربية السعودية</p>
              <p className="text-[10px] md:text-xs font-bold opacity-90">وزارة التعليم</p>
              <p className="text-[10px] md:text-xs font-bold opacity-90">الإدارة العامة للتعليم بمحافظة جدة</p>
              <p className="text-sm md:text-lg font-black mt-2 text-[#00a18e] border-r-4 border-[#00a18e] pr-3">ثانوية الأمير عبدالمجيد الأولى</p>
           </div>
           <div className="order-1 md:order-2 flex-shrink-0">
              <img src="https://up6.cc/2026/01/176840436497671.png" className="h-24 md:h-32 object-contain drop-shadow-2xl" alt="Logo" />
           </div>
           <div className="flex flex-col items-center md:items-end gap-2 order-3 flex-1">
              <div className="bg-black/30 px-6 py-3 rounded-2xl border border-white/10 text-center md:text-right">
                <p className="text-[10px] opacity-70 font-bold text-emerald-400">المدير المسؤول،</p>
                <p className="text-sm font-black">{userProfile.full_name}</p>
              </div>
              <button onClick={() => supabase.auth.signOut()} className="text-red-300 hover:text-red-100 text-[10px] font-bold flex items-center gap-1 transition-colors">
                <LogOut className="w-3 h-3" /> تسجيل الخروج
              </button>
           </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-6 -mt-10 space-y-8 relative z-20 pb-20 no-print">
        <div className="flex flex-col md:flex-row gap-6">
           <div className="flex-1 grid grid-cols-2 md:grid-cols-3 gap-4">
              <button onClick={() => setView('active')} className={`p-6 rounded-[2.5rem] border shadow-xl flex items-center gap-4 transition-all ${view === 'active' ? 'bg-white border-emerald-500 ring-4 ring-emerald-500/10' : 'bg-slate-50 border-transparent opacity-60'}`}>
                 <div className="w-12 h-12 bg-emerald-50 rounded-2xl flex items-center justify-center text-emerald-600"><Users /></div>
                 <div className="text-right">
                    <p className="text-[10px] font-black text-slate-400">المعتمدون</p>
                    <p className="text-2xl font-black text-slate-800">{activeStaff.length}</p>
                 </div>
              </button>
              <button onClick={() => setView('pending')} className={`p-6 rounded-[2.5rem] border shadow-xl flex items-center gap-4 transition-all relative ${view === 'pending' ? 'bg-white border-amber-500 ring-4 ring-amber-500/10' : 'bg-slate-50 border-transparent opacity-60'}`}>
                 <div className="w-12 h-12 bg-amber-50 rounded-2xl flex items-center justify-center text-amber-600"><UserPlus /></div>
                 <div className="text-right">
                    <p className="text-[10px] font-black text-slate-400">طلبات جديدة</p>
                    <p className="text-2xl font-black text-slate-800">{pendingStaff.length}</p>
                 </div>
                 {pendingStaff.length > 0 && <span className="absolute top-4 left-4 bg-red-500 w-3 h-3 rounded-full animate-ping"></span>}
              </button>
           </div>
           <div className="bg-white p-4 rounded-[2.5rem] shadow-xl border border-slate-100 flex items-center px-8 flex-1">
              <Search className="text-slate-300 ml-4" />
              <input type="text" placeholder="بحث باسم الموظف أو رقم الجوال..." className="bg-transparent border-none outline-none w-full font-bold text-sm" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
           </div>
        </div>

        <div className="bg-white rounded-[4rem] shadow-2xl border border-slate-100 overflow-hidden min-h-[400px]">
          {loading ? (
             <div className="flex flex-col items-center justify-center py-40 gap-4">
                <Loader2 className="w-12 h-12 text-emerald-600 animate-spin" />
                <p className="text-slate-400 font-bold">جاري المزامنة...</p>
             </div>
          ) : (
            <div className="p-10">
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {(view === 'active' ? activeStaff : pendingStaff).map(s => {
                  const ev = evaluations[s.id];
                  const info = ev ? getGradeInfo(ev.total_score) : null;
                  const corrupted = isArabicMobile(s.mobile);

                  return (
                    <div key={s.id} className={`bg-white p-6 rounded-[2.5rem] border flex flex-col gap-6 shadow-sm hover:shadow-xl transition-all group ${corrupted ? 'border-red-200 bg-red-50/20' : 'border-slate-100'}`}>
                        <div className="flex items-center gap-4">
                           <div className={`w-14 h-14 rounded-2xl flex items-center justify-center font-black text-xl shadow-sm transition-colors ${corrupted ? 'bg-red-100 text-red-600' : 'bg-slate-50 text-[#0f4c4c] group-hover:bg-[#0f4c4c] group-hover:text-white'}`}>{s.full_name.charAt(0)}</div>
                           <div className="text-right flex-1">
                              <p className="font-black text-slate-800 text-lg leading-tight">{s.full_name}</p>
                              <p className={`text-[11px] font-bold mt-1 ${corrupted ? 'text-red-500' : 'text-slate-400'}`}>
                                {corrupted ? 'حساب تالف (أرقام عربية)' : s.role} | {s.mobile}
                              </p>
                           </div>
                           {corrupted && <AlertTriangle className="w-5 h-5 text-red-500 animate-bounce" />}
                        </div>

                        {corrupted ? (
                          <div className="bg-red-100/50 p-4 rounded-2xl text-[10px] text-red-700 font-bold">
                            هذا الحساب سجل بأرقام عربية ولن يتمكن من الدخول. يرجى حذفه ليتمكن الموظف من التسجيل من جديد.
                          </div>
                        ) : view === 'active' && (
                          <div className="flex justify-between items-center bg-slate-50 p-4 rounded-2xl">
                             <div className="text-right">
                                <p className="text-[10px] text-slate-400 font-bold">التقدير</p>
                                <p className="text-sm font-black text-[#0f4c4c]">{info ? `${info.label}` : '--'}</p>
                             </div>
                             <div className="flex gap-1">
                                <button onClick={() => openWhatsApp(s, ev)} className="p-2 text-emerald-600 hover:bg-emerald-50 rounded-xl"><MessageCircle className="w-5 h-5" /></button>
                                {ev && <button onClick={() => handlePrint(s, ev)} className="p-2 text-slate-400 hover:bg-slate-100 rounded-xl"><Printer className="w-5 h-5" /></button>}
                             </div>
                          </div>
                        )}

                        <div className="flex gap-2">
                           {!s.is_approved && !corrupted && (
                             <button disabled={processingId === s.id} onClick={() => approveUser(s.id)} className="flex-1 bg-emerald-600 text-white py-3.5 rounded-2xl hover:bg-emerald-700 transition shadow-lg flex items-center justify-center gap-2">
                                <Check className="w-5 h-5" /> <span className="text-xs font-black">اعتماد</span>
                             </button>
                           )}
                           {view === 'active' && !corrupted && (
                             <button onClick={() => setSelectedStaff(s)} className="flex-1 bg-[#0f4c4c] text-white py-3.5 rounded-2xl hover:bg-black transition flex items-center justify-center gap-2">
                                <UserCheck className="w-5 h-5" /> <span className="text-xs font-black">{ev ? 'تعديل التقييم' : 'تقييم الآن'}</span>
                             </button>
                           )}
                           <button disabled={processingId === s.id} onClick={() => deleteUser(s.id)} className={`px-4 py-3.5 rounded-2xl transition flex items-center justify-center ${corrupted ? 'flex-1 bg-red-600 text-white hover:bg-red-700' : 'bg-red-50 text-red-600 hover:bg-red-600 hover:text-white'}`}>
                              {processingId === s.id ? <Loader2 className="w-5 h-5 animate-spin" /> : <UserMinus className="w-5 h-5" />}
                              {corrupted && <span className="mr-2 text-xs font-black">حذف الحساب الموحد</span>}
                           </button>
                        </div>
                    </div>
                  );
                })}
              </div>
            </div>
          )}
        </div>
      </main>

      {selectedStaff && <EvaluationModal staff={selectedStaff} onClose={() => { setSelectedStaff(null); fetchData(); }} />}
      {evaluationToShow && <PrintableReport staff={evaluationToShow.staff} evaluation={evaluationToShow.evaluation} principalName={userProfile.full_name} />}
    </div>
  );
};

export default PrincipalDashboard;

import React from 'react';
import { Profile, Evaluation } from '../types';
import { CRITERIA_MAP } from '../constants';

interface Props {
  staff: Profile;
  evaluation: Evaluation;
  principalName: string;
}

const PrintableReport: React.FC<Props> = ({ staff, evaluation, principalName }) => {
  const criteria = CRITERIA_MAP[staff.role] || [];
  const isCondensed = criteria.length > 14;

  const getRating = (percentage: number) => {
    let points = 1;
    let label = 'غير مرضي';
    if (percentage >= 90) { points = 5; label = 'مثالي'; }
    else if (percentage >= 80) { points = 4; label = 'تخطى التوقعات'; }
    else if (percentage >= 70) { points = 3; label = 'وافق التوقعات'; }
    else if (percentage >= 60) { points = 2; label = 'بحاجة إلى تطوير'; }
    else { points = 1; label = 'غير مرضي'; }
    return { label, points: points.toString() };
  };

  const rating = getRating(evaluation.total_score);
  const finalFrom5 = (evaluation.total_score / 100) * 5;

  return (
    <div className={`printable-area font-official text-black bg-white ${isCondensed ? 'text-[9.5pt]' : 'text-[11pt]'}`} style={{ lineHeight: isCondensed ? '1.15' : '1.4' }}>

      {/* الترويسة الرسمية */}
      <table className={`w-full border-none ${isCondensed ? 'mb-2' : 'mb-6'}`}>
        <tbody>
          <tr>
            <td className="w-1/3 text-right align-top space-y-0.5">
              <p className="font-bold">المملكة العربية السعودية</p>
              <p>وزارة التعليم</p>
              <p>الإدارة العامة للتعليم بجدة</p>
              <p className="font-bold">ثانوية الأمير عبدالمجيد الأولى</p>
            </td>
            <td className="w-1/3 text-center align-middle">
              <img src="https://up6.cc/2026/01/176840436497671.png" className={`${isCondensed ? 'h-14' : 'h-20'} mb-1 mx-auto`} alt="Logo" />
              <h1 className={`${isCondensed ? 'text-base' : 'text-lg'} font-bold border-b-2 border-black inline-block pb-0.5 uppercase tracking-tighter`}>بطاقة الأداء الوظيفي</h1>
            </td>
            <td className="w-1/3 text-left align-top font-sans" style={{ fontSize: isCondensed ? '8pt' : '9pt' }}>
              <p>التاريخ: {new Date(evaluation.created_at).toLocaleDateString('ar-SA')}</p>
              <p>العام الدراسي: 1447هـ</p>
              <p className="text-gray-400">ID: {evaluation.id.split('-')[0].toUpperCase()}</p>
            </td>
          </tr>
        </tbody>
      </table>

      {/* بوكس النتيجة المئوية ومن 5 */}
      <div className={`border-2 border-black ${isCondensed ? 'p-2 mb-2' : 'p-4 mb-6'} flex justify-between items-center rounded-sm bg-gray-50/30`}>
        <div className={isCondensed ? 'space-y-0.5' : 'space-y-2'}>
          <p><span className="font-bold">اسم الموظف:</span> {staff.full_name}</p>
          <p><span className="font-bold">المسمى الوظيفي:</span> {staff.role}</p>
          <p><span className="font-bold">المقيّم:</span> {principalName}</p>
        </div>
        <div className="flex items-center">
          <div className={`text-center ${isCondensed ? 'px-4' : 'px-8'}`}>
            <p className="text-[9px] font-bold text-gray-500 mb-0.5 uppercase">الدرجة النهائية</p>
            <div className={`${isCondensed ? 'text-2xl' : 'text-4xl'} font-bold font-sans`}>{finalFrom5.toFixed(2)} <span className="text-xs opacity-40">/ 5</span></div>
          </div>
          <div className={`w-px ${isCondensed ? 'h-10' : 'h-16'} bg-black`}></div>
          <div className={`text-center ${isCondensed ? 'px-4' : 'px-8'}`}>
            <p className="text-[9px] font-bold text-gray-500 mb-0.5 uppercase">النسبة المئوية</p>
            <div className={`${isCondensed ? 'text-2xl' : 'text-4xl'} font-bold font-sans`}>{Math.round(evaluation.total_score)}%</div>
            <p className="text-[10px] font-bold mt-0.5">{rating.label}</p>
          </div>
        </div>
      </div>

      {/* جدول البيانات الرئيسي */}
      <table className="w-full border-collapse border-2 border-black mb-2" style={{ fontSize: isCondensed ? '9pt' : '10pt' }}>
        <thead>
          <tr className="bg-gray-100 border-b-2 border-black">
            <th className="border-l-2 border-black p-1.5 w-8 text-center">م</th>
            <th className="border-l-2 border-black p-1.5 text-right">عناصر التقييم (المعايير والواجبات)</th>
            <th className="border-l-2 border-black w-24 text-center">الوزن النسبي</th>
            <th className="p-1.5 w-28 text-center">سلم التقدير (1-5)</th>
          </tr>
        </thead>
        <tbody>
          {criteria.map((c, idx) => {
            const rawRating = evaluation.scores[c.id] || 1;
            return (
              <tr key={c.id} className="border-b border-black">
                <td className={`border-l-2 border-black ${isCondensed ? 'p-1' : 'p-1.5'} text-center font-sans`}>{idx + 1}</td>
                <td className={`border-l-2 border-black ${isCondensed ? 'p-1' : 'p-1.5'} pr-2 font-bold`}>{c.text}</td>
                <td className={`border-l-2 border-black ${isCondensed ? 'p-1' : 'p-1.5'} text-center font-bold font-sans`}>
                  {(c.weight * 100).toFixed(0)}%
                </td>
                <td className={`${isCondensed ? 'p-1' : 'p-1.5'} text-center`}>
                  <div className="flex justify-center gap-1" dir="ltr">
                    {[1, 2, 3, 4, 5].map(v => (
                      <span key={v} className={`inline-block border border-black ${isCondensed ? 'w-4 h-4 text-[8pt]' : 'w-5 h-5 text-[9pt]'} flex items-center justify-center font-bold ${v === rawRating ? 'bg-black text-white' : ''}`}>
                        {v}
                      </span>
                    ))}
                  </div>
                </td>
              </tr>
            );
          })}
          <tr className="bg-gray-100 font-bold">
            <td colSpan={2} className={`border-l-2 border-black ${isCondensed ? 'p-2' : 'p-3'} pr-2 text-base`}>التقدير العام للأداء (الدرجة النهائية)</td>
            <td className={`border-l-2 border-black ${isCondensed ? 'p-2' : 'p-3'} text-center font-sans text-base`}>100%</td>
            <td className={`${isCondensed ? 'p-2' : 'p-3'} text-center text-xl font-sans underline decoration-double`}>
              {finalFrom5.toFixed(2)}
            </td>
          </tr>
